// ====== LOCAL SQLITE BACKEND SYNC ======
// The browser keeps a small local cache for instant/offline use. When this project
// is run with `node server.js`, the same account/app state is persisted in SQLite.
const BACKEND_BASE=(location.protocol==='http:'||location.protocol==='https:') && location.port==='3000' ? '' : 'http://localhost:3000';
let backendOnline=false;
async function apiRequest(path, options={}){
  try{
    const r=await fetch(BACKEND_BASE+path,Object.assign({headers:{'Content-Type':'application/json'}},options));
    if(!r.ok)throw new Error('HTTP '+r.status);
    backendOnline=true;
    return await r.json();
  }catch(e){ backendOnline=false; return null; }
}
function backendUser(){return currentUser||getSession();}
async function syncAccountToBackend(acct){
  if(!acct)return;
  await apiRequest('/api/auth/upsert',{method:'POST',body:JSON.stringify(acct)});
}
async function hydrateBackendState(username){
  if(!username)return;
  const data=await apiRequest('/api/state/all?username='+encodeURIComponent(username));
  if(!data||!data.state)return;

  // SQLite is the source of truth when it is reachable. Clear the shared tracker
  // cache first so switching accounts can never show another user's local data.
  ['climacrave_diary','climacrave_water','climacrave_weather'].forEach(function(kind){
    try{localStorage.removeItem(kind);}catch(e){}
  });

  Object.keys(data.state).forEach(function(kind){
    try{
      // Settings are stored in SQLite under the compact key "settings", while the
      // browser cache is namespaced per account.
      var localKey=(kind==='settings')?settingsKey(username):(kind==='favorite_city'?favoriteCityKey(username):kind);
      if(kind==='favorite_city' && data.state[kind]===null){localStorage.removeItem(localKey);}
      else localStorage.setItem(localKey,JSON.stringify(data.state[kind]));
    }catch(e){}
  });
  loadSettingsForLocal(username);
  try{renderDiary();}catch(e){}
  if(lastWeather){displayWeather(lastWeather);displayRecommendations(recommendFood(lastWeather,settings.recoCount),lastWeather);}
}

let settings={apiEnabled:true,provider:'openmeteo',apiKey:'',unit:'metric',recoCount:8,recommendationMode:'rules',customApiUrl:'',customMapping:'',timeFormat:'12h',autoLocation:true,calorieGoal:2000,proteinGoal:150,carbGoal:250,fatGoal:70,waterGoal:8,foodApi:'openfoodfacts',edamamAppId:'',edamamAppKey:'',usdaApiKey:''};
const DEFAULT_SETTINGS=Object.assign({},settings);
let lastWeather=null;
function settingsKey(username){return 'climacrave_settings_'+username.toLowerCase();}
function loadSettingsForLocal(username){
  settings=Object.assign({},DEFAULT_SETTINGS);
  try{
    const s=localStorage.getItem(settingsKey(username));
    if(s){
      settings=Object.assign(settings,JSON.parse(s));
      if(!settings.provider||(settings.provider==='openweathermap'&&!settings.apiKey)){
        settings.provider='openmeteo';
      }
      return;
    }
    const legacy=localStorage.getItem('climacrave_settings');
    if(legacy){
      settings=Object.assign(settings,JSON.parse(legacy));
      if(!settings.provider||(settings.provider==='openweathermap'&&!settings.apiKey)){
        settings.provider='openmeteo';
      }
      localStorage.removeItem('climacrave_settings');
      saveSettingsFor(username);
    }
  }catch(e){}
}
async function loadSettingsFor(username){
  loadSettingsForLocal(username);
  await hydrateBackendState(username);
}
function saveSettingsFor(username){
  try{localStorage.setItem(settingsKey(username),JSON.stringify(settings));}catch(e){}
  if(username)apiRequest('/api/state/settings',{method:'PUT',body:JSON.stringify({username:username,value:settings})});
}

