function searchBuiltinFoods(q){
  var ql=q.toLowerCase().trim();
  var results=[];
  for(var i=0;i<BUILTIN_FOODS.length;i++){
    var f=BUILTIN_FOODS[i];
    var name=f.n.toLowerCase();
    if(name.indexOf(ql)>=0||ql.indexOf(name)>=0){
      results.push(f);
    }
  }
  results.sort(function(a,b){
    var an=a.n.toLowerCase(),bn=b.n.toLowerCase();
    var ai=an.indexOf(ql),bi=bn.indexOf(ql);
    if(ai!==bi)return ai-bi;
    return an.length-bn.length;
  });
  return results.slice(0,15);
}

function renderBuiltinResults(results,out){
  if(!results.length){return false;}
  out.innerHTML=results.map(function(f){
    return '<button class="cs-result" onclick="pickCustomFood(this)" data-name="'+escHtml(f.n)+'" data-cal="'+f.c+'" data-protein="'+f.p+'" data-carbs="'+(f.cb||0)+'" data-fat="'+(f.f||0)+'">'+
      '<span class="cs-name">'+escHtml(f.n)+'</span><span class="cs-cal">'+f.c+' cal / 100g \u00b7 '+f.p+'g P \u00b7 '+(f.cb||0)+'g C \u00b7 '+(f.f||0)+'g F</span></button>';
  }).join('');
  return true;
}

function searchCustomFood(){
  const g=goals();
  const q=document.getElementById('customSearchInput').value.trim();
  const out=document.getElementById('customSearchResults');
  if(!q){out.innerHTML='<div class="trk-note">Type a food name to search.</div>';return;}
  // Step 1: Always search built-in Indian food database first
  var builtin=searchBuiltinFoods(q);
  if(builtin.length>0){
    var apiNote='<div style="margin-bottom:8px;font-size:11px;color:#7d8aa8">Showing '+builtin.length+' results from built-in Indian food database</div>';
    out.innerHTML=apiNote;
    renderBuiltinResults(builtin,out);
    return;
  }
  // Step 2: No built-in results, fall back to external API
  const api=g.foodApi||'openfoodfacts';
  out.innerHTML='<div class="trk-note">No built-in match. Searching external API...</div>';
  if(api==='edamam'){
    if(!g.edamamAppId||!g.edamamAppKey){
      out.innerHTML='<div class="trk-note err">Add your Edamam App ID and App Key in Settings first, or switch to Open Food Facts (free, no key needed).</div>';
      return;
    }
    searchEdamam(q,g,out);
  }else if(api==='usda'){
    if(!g.usdaApiKey){
      out.innerHTML='<div class="trk-note err">Add your USDA API Key in Settings first, or switch to Open Food Facts (free, no key needed).</div>';
      return;
    }
    searchUSDA(q,g,out);
  }else{
    searchOpenFoodFacts(q,out);
  }
}

function searchOpenFoodFacts(q,out){
  out.innerHTML='<div class="trk-note"><span class="loader"></span> Searching Open Food Facts\u2026</div>';
  var url='https://world.openfoodfacts.org/cgi/search.pl?search_terms='+encodeURIComponent(q)+'&search_simple=1&action=process&json=1&page_size=20';
  fetch(url).then(function(r){
    if(!r.ok)throw new Error('Open Food Facts returned '+r.status);
    return r.json();
  }).then(function(data){
    var products=(data&&Array.isArray(data.products)?data.products:[]).filter(function(p){
      return p&&p.product_name&&p.nutriments&&isFinite(p.nutriments['energy-kcal_100g']);
    }).slice(0,12);
    if(!products.length){out.innerHTML='<div class="trk-note">No results for \u201c'+escHtml(q)+'\u201d.</div>';return;}
    out.innerHTML=products.map(function(p){
      var cal=Math.round(p.nutriments['energy-kcal_100g']);
      var protein=Math.round(p.nutriments.proteins_100g||0);
      var carbs=Math.round(p.nutriments.carbohydrates_100g||0);
      var fat=Math.round(p.nutriments.fat_100g||0);
      var name=escHtml(p.product_name);
      var brand=p.brands?escHtml(p.brands):'';
      return '<button class="cs-result" onclick="pickCustomFood(this)" data-name="'+name+'" data-cal="'+cal+'" data-protein="'+protein+'" data-carbs="'+carbs+'" data-fat="'+fat+'">'+
        '<span class="cs-name">'+name+(brand?' <span style="opacity:.6;font-size:11px">'+brand+'</span>':'')+'</span><span class="cs-cal">'+cal+' cal / 100g \u00b7 '+protein+'g P \u00b7 '+carbs+'g C \u00b7 '+fat+'g F</span></button>';
    }).join('');
  }).catch(function(e){
    out.innerHTML='<div class="trk-note err">Search failed: '+escHtml(e.message)+'</div>';
  });
}

function searchEdamam(q,g,out){
  out.innerHTML='<div class="trk-note"><span class="loader"></span> Searching Edamam\u2026</div>';
  var url='https://api.edamam.com/api/food-database/v2/parser?app_id='+encodeURIComponent(g.edamamAppId)+'&app_key='+encodeURIComponent(g.edamamAppKey)+'&ingr='+encodeURIComponent(q);
  fetch(url).then(function(r){
    if(!r.ok)throw new Error('Edamam returned '+r.status);
    return r.json();
  }).then(function(data){
    var seen={};
    var hints=(data&&Array.isArray(data.hints)?data.hints:[]).map(function(h){
      return h&&h.food?h.food:null;
    }).filter(function(f){
      if(!f||!f.label)return false;
      var cal=f.nutrients&&f.nutrients.ENERC_KCAL;
      if(!isFinite(cal))return false;
      var k=f.label.toLowerCase();
      if(seen[k])return false;
      seen[k]=1;return true;
    }).slice(0,12);
    if(!hints.length){out.innerHTML='<div class="trk-note">No results for \u201c'+escHtml(q)+'\u201d.</div>';return;}
    out.innerHTML=hints.map(function(f){
      var cal=Math.round(f.nutrients.ENERC_KCAL);
      var prot=Math.round((f.nutrients.PROCNT)||0);
      var carbs=Math.round((f.nutrients.CHOCDF)||0);
      var fat=Math.round((f.nutrients.FAT)||0);
      return '<button class="cs-result" onclick="pickCustomFood(this)" data-name="'+escHtml(f.label)+'" data-cal="'+cal+'" data-protein="'+prot+'" data-carbs="'+carbs+'" data-fat="'+fat+'">'+
        '<span class="cs-name">'+escHtml(f.label)+'</span><span class="cs-cal">'+cal+' cal / 100g \u00b7 '+prot+'g P \u00b7 '+carbs+'g C \u00b7 '+fat+'g F</span></button>';
    }).join('');
  }).catch(function(e){
    out.innerHTML='<div class="trk-note err">Search failed: '+escHtml(e.message)+'</div>';
  });
}

function searchUSDA(q,g,out){
  out.innerHTML='<div class="trk-note"><span class="loader"></span> Searching USDA\u2026</div>';
  var url='https://api.nal.usda.gov/fdc/v1/foods/search?api_key='+encodeURIComponent(g.usdaApiKey)+'&query='+encodeURIComponent(q)+'&pageSize=12';
  fetch(url).then(function(r){
    if(!r.ok)throw new Error('USDA returned '+r.status);
    return r.json();
  }).then(function(data){
    var foods=(data&&Array.isArray(data.foods)?data.foods:[]).filter(function(f){
      return f&&f.description&&f.foodNutrients;
    });
    if(!foods.length){out.innerHTML='<div class="trk-note">No results for \u201c'+escHtml(q)+'\u201d.</div>';return;}
    out.innerHTML=foods.map(function(f){
      var cal=0,prot=0;
      for(var i=0;i<f.foodNutrients.length;i++){
        var n=f.foodNutrients[i];
        if(n.nutrientName==='Energy'&&n.unitName==='KCAL')cal=n.value||0;
        if(n.nutrientName==='Protein'&&n.unitName==='G')prot=n.value||0;
      }
      if(!isFinite(cal)||cal<=0)return '';
      cal=Math.round(cal);prot=Math.round(prot);
      var usdaCarbs=0,usdaFat=0;
      for(var j=0;j<f.foodNutrients.length;j++){
        var nu=f.foodNutrients[j];
        if(nu.nutrientName==='Carbohydrate, by difference'&&nu.unitName==='G')usdaCarbs=nu.value||0;
        if(nu.nutrientName==='Total lipid (fat)'&&nu.unitName==='G')usdaFat=nu.value||0;
      }
      usdaCarbs=Math.round(usdaCarbs);usdaFat=Math.round(usdaFat);
      return '<button class="cs-result" onclick="pickCustomFood(this)" data-name="'+escHtml(f.description)+'" data-cal="'+cal+'" data-protein="'+prot+'" data-carbs="'+usdaCarbs+'" data-fat="'+usdaFat+'">'+
        '<span class="cs-name">'+escHtml(f.description)+'</span><span class="cs-cal">'+cal+' cal / 100g \u00b7 '+prot+'g P \u00b7 '+usdaCarbs+'g C \u00b7 '+usdaFat+'g F</span></button>';
    }).filter(function(s){return s;}).join('');
  }).catch(function(e){
    out.innerHTML='<div class="trk-note err">Search failed: '+escHtml(e.message)+'</div>';
  });
}

function pickCustomFood(btn){
  openCustomPortionPopup(btn.getAttribute('data-name'),btn.getAttribute('data-cal'),btn.getAttribute('data-protein')||0,btn.getAttribute('data-carbs')||0,btn.getAttribute('data-fat')||0);
}

// ====== WATER ======
// New simple renderWater - no SVG ring, just a clean progress bar
function renderWater(){
  var g=goals();
  var key=todayKey();
  var log=waterFor(key);
  var totalMl=log.reduce(function(s,e){return s+(Number(e.ml)||0);},0);
  var glasses=totalMl/250;
  var goalMl=g.waterGoal*250;
  var pct=goalMl>0?Math.min(1,totalMl/goalMl):0;
  var overGoal=totalMl>goalMl;
  var barColor=overGoal?'#4caf50':'#2196f3';

  var box=document.getElementById('waterContent');
  if(!box)return;

  var html='';
  // Simple header with big number
  html+='<div style="text-align:center;padding:16px 0 12px">';
  html+='<div style="font-size:36px;font-weight:800;color:'+barColor+'">'+Math.round(glasses*10)/10+'</div>';
  html+='<div style="font-size:12px;opacity:.6">of '+g.waterGoal+' glasses ('+fmtNum(goalMl)+'ml)</div>';
  html+='</div>';

  // Simple progress bar
  html+='<div style="background:rgba(255,255,255,.1);border-radius:10px;height:24px;overflow:hidden;margin-bottom:6px;position:relative">';
  html+='<div style="height:100%;width:'+Math.round(pct*100)+'%;background:'+barColor+';border-radius:10px;transition:width .3s;display:flex;align-items:center;justify-content:center">';
  if(pct>0.15){
    html+='<span style="font-size:11px;font-weight:700;color:#fff">'+Math.round(pct*100)+'%</span>';
  }
  html+='</div></div>';

  // Total text
  html+='<div style="text-align:center;font-size:12px;margin-bottom:14px">';
  html+='<span style="font-weight:700">'+fmtNum(totalMl)+'ml</span>';
  html+='<span style="opacity:.5"> consumed</span>';
  if(overGoal){
    html+=' <span style="color:#4caf50;font-weight:700">Goal reached!</span>';
  }
  html+='</div>';

  // Quick add buttons
  html+='<div class="water-quick">';
  html+='<button onclick="addWater(250)">+1 Glass (250ml)</button>';
  html+='<button onclick="addWater(1000)">+1 Bottle (1L)</button>';
  html+='<button onclick="addWater(500)">+500ml</button>';
  html+='<button onclick="addWater(250)">+250ml</button>';
  html+='</div>';

  // Custom add
  html+='<div class="water-custom">';
  html+='<input type="number" id="waterCustomVal" placeholder="Amount" min="0" step="any" style="flex:1;min-width:0">';
  html+='<select id="waterCustomUnit" style="width:auto">';
  html+='<option value="glasses">glasses</option>';
  html+='<option value="bottles">bottles</option>';
  html+='<option value="liters">liters</option>';
  html+='<option value="ml" selected>ml</option>';
  html+='</select>';
  html+='<button class="btn btn-primary" style="font-size:12px;padding:10px 14px;flex-shrink:0" onclick="addWaterCustom()">Add</button>';
  html+='</div>';

  // Undo button
  html+='<button class="btn btn-ghost" id="waterUndoBtn" style="width:100%;justify-content:center;margin-top:8px;color:#e8ecf4" onclick="undoLastWater()">Undo Last Add</button>';

  // Today's log
  html+='<div class="trk-sub-title" style="margin-top:14px">Today\'s Log</div>';
  if(!log.length){
    html+='<div class="trk-note">No water logged yet today.</div>';
  }else{
    html+='<div style="display:flex;flex-direction:column;gap:4px">';
    log.forEach(function(e,i){
      html+='<div class="water-row"><span class="water-amt">+ '+fmtNum(e.ml)+'ml</span>'+
        '<span class="water-time">'+escHtml(e.time||'')+'</span>'+
        '<button class="btn-icon diary-del" title="Delete" onclick="deleteWaterEntry('+i+')">X</button></div>';
    });
    html+='</div>';
  }

  box.innerHTML=html;
  var undo=document.getElementById('waterUndoBtn');
  if(undo)undo.disabled=!log.length;
}


function addWater(ml){
  const amount=Math.round(Number(ml)||0);
  if(amount<=0){showToast('Enter an amount above zero',true);return;}
  const key=todayKey();
  const all=getWater();
  if(!Array.isArray(all[key]))all[key]=[];
  all[key].push({ml:amount,time:nowTimeLabel(),timestamp:Date.now()});
  if(writeStore(WATER_KEY,all)){renderWater();showToast('Added '+fmtNum(amount)+'ml of water');}
}
function addWaterCustom(){
  const v=parseFloat(document.getElementById('waterCustomVal').value);
  const unit=document.getElementById('waterCustomUnit').value;
  if(!isFinite(v)||v<=0){showToast('Enter an amount above zero',true);return;}
  const factor={glasses:250,bottles:1000,liters:1000,ml:1}[unit]||1;
  addWater(v*factor);
  document.getElementById('waterCustomVal').value='';
}
function undoLastWater(){
  const key=todayKey();
  const all=getWater();
  const log=Array.isArray(all[key])?all[key]:[];
  if(!log.length){showToast('Nothing to undo',true);return;}
  const last=log.pop();
  if(log.length)all[key]=log;else delete all[key];
  if(writeStore(WATER_KEY,all)){renderWater();showToast('Removed last entry ('+fmtNum(last.ml)+'ml)');}
}
function deleteWaterEntry(i){
  const key=todayKey();
  const all=getWater();
  const log=Array.isArray(all[key])?all[key]:[];
  if(i<0||i>=log.length)return;
  const e=log[i];
  log.splice(i,1);
  if(log.length)all[key]=log;else delete all[key];
  if(writeStore(WATER_KEY,all)){renderWater();showToast('Removed '+fmtNum(e.ml)+'ml entry');}
}

// ====== STATS ======
function buildBarChart(series,goal,unit,color){
  const max=Math.max(goal,Math.max.apply(null,series.map(function(s){return s.value;})),1);
  const goalPct=Math.min(100,goal/max*100);
  const bars=series.map(function(s){
    const h=Math.max(s.value>0?3:0,s.value/max*100);
    return '<div class="chart-col">'+
      '<div class="chart-val">'+(s.value?fmtNum(s.value):'')+'</div>'+
      '<div class="chart-track"><div class="chart-fill" style="height:'+h.toFixed(1)+'%;background:'+color+'"></div></div>'+
      '<div class="chart-lbl">'+escHtml(s.label)+'</div></div>';
  }).join('');
  // The goal line lives in an overlay that spans exactly the bar track area, so its
  // percentage is measured against the same box the bar heights are.
  return '<div class="chart-wrap"><div class="chart-plot">'+
    '<div class="chart-goal-layer"><div class="chart-goal" style="bottom:'+goalPct.toFixed(1)+'%">'+
    '<span>goal '+fmtNum(goal)+unit+'</span></div></div>'+
    bars+'</div></div>';
}
// ====== STATS HISTORY: unlimited saved data + professional date navigation ======

// The selected date controls both the day summary and the seven-day charts. It is
// intentionally not capped to 30 days or four weeks: any saved historical date can
// be opened through the calendar picker.
var statsViewDate=null;

function statsNormalizeDate(d){
  var x=d instanceof Date?new Date(d):new Date();
  if(isNaN(x.getTime()))x=new Date();
  x.setHours(12,0,0,0);
  return x;
}
function statsToday(){return statsNormalizeDate(new Date());}
function statsCurrentDate(){
  var d=statsViewDate?statsNormalizeDate(statsViewDate):statsToday();
  var t=statsToday();
  if(d>t)d=t;
  return d;
}
function statsSelectedKey(){return todayKey(statsCurrentDate());}
function statsDateFromKey(key){
  var m=String(key||'').match(/^(\d{4})-(\d{2})-(\d{2})$/);
  if(!m)return null;
  var d=new Date(Number(m[1]),Number(m[2])-1,Number(m[3]),12,0,0,0);
  if(isNaN(d.getTime())||todayKey(d)!==key)return null;
  return d;
}
function statsSevenDaysEnding(endDate){
  var end=statsNormalizeDate(endDate||statsCurrentDate());
  var out=[];
  for(var i=6;i>=0;i--){var d=new Date(end);d.setDate(end.getDate()-i);out.push(d);}
  return out;
}
function statsShortDate(d){
  return d.toLocaleDateString('en-US',{month:'short',day:'numeric',year:d.getFullYear()!==new Date().getFullYear()?'numeric':undefined});
}
function statsLongDate(d){
  return d.toLocaleDateString('en-US',{weekday:'long',month:'long',day:'numeric',year:'numeric'});
}
function statsRangeLabel(days){
  if(!days||!days.length)return '';
  var a=days[0],b=days[days.length-1];
  if(a.getFullYear()===b.getFullYear()){
    if(a.getMonth()===b.getMonth())return a.toLocaleDateString('en-US',{month:'short',day:'numeric'})+' – '+b.getDate()+', '+b.getFullYear();
    return a.toLocaleDateString('en-US',{month:'short',day:'numeric'})+' – '+b.toLocaleDateString('en-US',{month:'short',day:'numeric'})+', '+b.getFullYear();
  }
  return a.toLocaleDateString('en-US',{month:'short',day:'numeric',year:'numeric'})+' – '+b.toLocaleDateString('en-US',{month:'short',day:'numeric',year:'numeric'});
}
function statsWeatherIcon(wh){
  if(!wh)return '';
  var wm={'Clear':'☀','Clouds':'☁','Rain':'🌧','Drizzle':'🌦','Thunderstorm':'⚡','Snow':'❄','Mist':'🌫','Fog':'🌫','Haze':'🌫','Smoke':'🌫'};
  return wm[wh.cond]||'🌤';
}

// Save weather data when it loads. No retention cap: SQLite keeps every saved day.
function saveWeatherHistory(w){
  if(!w)return;
  try{
    var key='climacrave_weather';
    var data={};
    try{data=JSON.parse(localStorage.getItem(key)||'{}');}catch(e){}
    var dk=todayKey();
    data[dk]={temp:Math.round(w.tempC||0),cond:w.condition||'Unknown',desc:w.description||'',hum:w.humid||0,ts:Date.now()};
    writeStore(key,data);
  }catch(e){}
}
function getWeatherHistory(){try{return JSON.parse(localStorage.getItem('climacrave_weather')||'{}');}catch(e){return{}}}
function getWeatherForDate(dk){var d=getWeatherHistory();return d[dk]||null;}

function renderStatsDateSelector(){
  var box=document.getElementById('statsDateSelector');
  if(!box)return;
  var selected=statsCurrentDate();
  var selKey=todayKey(selected);
  var today=statsToday();
  var todayK=todayKey(today);
  var days=statsSevenDaysEnding(selected);
  var isToday=selKey===todayK;
  var nextDayDisabled=isToday?' disabled':'';
  var nextWeekDisabled=isToday?' disabled':'';

  var h='<section class="stats-history" aria-label="Stats history date selector">';
  h+='<div class="stats-history-head">'+
      '<div class="stats-history-title"><span class="stats-history-kicker">History</span><strong>'+escHtml(statsLongDate(selected))+'</strong><small>Choose any saved day. Your history is not limited to 30 days.</small></div>'+
      '<button type="button" class="stats-today-btn" onclick="statsGoToday()"'+(isToday?' disabled':'')+'>Today</button>'+
    '</div>';
  h+='<div class="stats-date-controls">'+
      '<button type="button" class="stats-nav-btn" onclick="statsShiftDate(-1)" aria-label="Previous day" title="Previous day">‹</button>'+
      '<label class="stats-date-picker" for="statsDatePicker"><span class="stats-date-icon">📅</span><span class="stats-date-copy"><small>Selected date</small><span>'+escHtml(statsShortDate(selected))+'</span></span>'+
        '<input id="statsDatePicker" type="date" value="'+selKey+'" max="'+todayK+'" onchange="statsPickDate(this.value)" aria-label="Choose history date">'+
        '<span class="stats-date-caret">⌄</span></label>'+
      '<button type="button" class="stats-nav-btn" onclick="statsShiftDate(1)" aria-label="Next day" title="Next day"'+nextDayDisabled+'>›</button>'+
    '</div>';

  h+='<div class="stats-week-strip" role="group" aria-label="Seven days ending on selected date">';
  days.forEach(function(d){
    var dk=todayKey(d),wh=getWeatherForDate(dk),active=dk===selKey,todayMark=dk===todayK;
    var list=diaryFor(dk),water=waterFor(dk);
    var hasData=list.length>0||water.length>0||!!wh;
    h+='<button type="button" class="stats-day-chip'+(active?' active':'')+(todayMark?' today':'')+(hasData?' has-data':'')+'" onclick="statsPickDate(\''+dk+'\')" aria-pressed="'+(active?'true':'false')+'">'+
       '<span class="stats-day-name">'+d.toLocaleDateString('en-US',{weekday:'short'})+'</span>'+
       '<span class="stats-day-num">'+d.getDate()+'</span>'+
       '<span class="stats-day-meta">'+(wh?statsWeatherIcon(wh)+(wh.temp!=null?' '+wh.temp+'°':''):(hasData?'•':''))+'</span>'+
       '</button>';
  });
  h+='</div>';

  h+='<div class="stats-range-nav">'+
      '<button type="button" onclick="statsShiftDate(-7)">← Previous 7 days</button>'+
      '<span>'+escHtml(statsRangeLabel(days))+'</span>'+
      '<button type="button" onclick="statsShiftDate(7)"'+nextWeekDisabled+'>Next 7 days →</button>'+
    '</div>';
  h+='</section>';
  box.innerHTML=h;
}

function statsPickDate(value){
  var d=statsDateFromKey(value);
  if(!d)return;
  var today=statsToday();
  if(d>today)d=today;
  statsViewDate=d;
  renderStatsDateSelector();
  renderStats();
}
function statsShiftDate(delta){
  var d=statsCurrentDate();
  d.setDate(d.getDate()+Number(delta||0));
  var today=statsToday();
  if(d>today)d=today;
  statsViewDate=d;
  renderStatsDateSelector();
  renderStats();
}
function statsGoToday(){
  statsViewDate=null;
  renderStatsDateSelector();
  renderStats();
}
function statsOpenDatePicker(){
  var el=document.getElementById('statsDatePicker');
  if(!el)return;
  try{if(typeof el.showPicker==='function')el.showPicker();else el.focus();}catch(e){try{el.focus();}catch(e2){}}
}

function renderGoalsTab(){
  var g=goals();
  var box=document.getElementById('goalsBody');
  if(!box)return;
  box.innerHTML=
    '<div style="margin-bottom:12px">'+
      '<div style="font-size:13px;font-weight:700;margin-bottom:10px">Daily Goals</div>'+
      '<div style="display:grid;grid-template-columns:1fr 1fr;gap:8px">'+
        '<div style="background:rgba(255,255,255,.05);border-radius:10px;padding:10px">'+
          '<div style="font-size:10px;opacity:.7;text-transform:uppercase;margin-bottom:4px">Calories</div>'+
          '<input type="number" id="trkGoalCal" value="'+g.calorieGoal+'" min="1" step="50" style="width:100%;background:rgba(255,255,255,.08);border:1px solid rgba(255,255,255,.15);border-radius:6px;padding:8px;color:#fff;font-size:14px">'+
          '<div style="font-size:9px;opacity:.5;margin-top:2px">kcal per day</div>'+
        '</div>'+
        '<div style="background:rgba(255,255,255,.05);border-radius:10px;padding:10px">'+
          '<div style="font-size:10px;opacity:.7;text-transform:uppercase;margin-bottom:4px">Protein</div>'+
          '<input type="number" id="trkGoalProt" value="'+g.proteinGoal+'" min="1" step="5" style="width:100%;background:rgba(255,255,255,.08);border:1px solid rgba(255,255,255,.15);border-radius:6px;padding:8px;color:#fff;font-size:14px">'+
          '<div style="font-size:9px;opacity:.5;margin-top:2px">grams per day</div>'+
        '</div>'+
        '<div style="background:rgba(255,255,255,.05);border-radius:10px;padding:10px">'+
          '<div style="font-size:10px;opacity:.7;text-transform:uppercase;margin-bottom:4px">Carbs</div>'+
          '<input type="number" id="trkGoalCarb" value="'+g.carbGoal+'" min="1" step="5" style="width:100%;background:rgba(255,255,255,.08);border:1px solid rgba(255,255,255,.15);border-radius:6px;padding:8px;color:#fff;font-size:14px">'+
          '<div style="font-size:9px;opacity:.5;margin-top:2px">grams per day</div>'+
        '</div>'+
        '<div style="background:rgba(255,255,255,.05);border-radius:10px;padding:10px">'+
          '<div style="font-size:10px;opacity:.7;text-transform:uppercase;margin-bottom:4px">Fat</div>'+
          '<input type="number" id="trkGoalFat" value="'+g.fatGoal+'" min="1" step="5" style="width:100%;background:rgba(255,255,255,.08);border:1px solid rgba(255,255,255,.15);border-radius:6px;padding:8px;color:#fff;font-size:14px">'+
          '<div style="font-size:9px;opacity:.5;margin-top:2px">grams per day</div>'+
        '</div>'+
      '</div>'+
      '<div style="background:rgba(255,255,255,.05);border-radius:10px;padding:10px;margin-top:8px">'+
        '<div style="font-size:10px;opacity:.7;text-transform:uppercase;margin-bottom:4px">Water</div>'+
        '<input type="number" id="trkGoalWater" value="'+g.waterGoal+'" min="1" step="1" style="width:100%;background:rgba(255,255,255,.08);border:1px solid rgba(255,255,255,.15);border-radius:6px;padding:8px;color:#fff;font-size:14px">'+
        '<div style="font-size:9px;opacity:.5;margin-top:2px">glasses per day (1 glass = 250ml)</div>'+
      '</div>'+
      '<button class="btn btn-primary" style="width:100%;margin-top:10px;padding:10px;font-size:13px" onclick="saveTrkGoals()">Save Goals</button>'+
    '</div>';
}

function saveTrkGoals(){
  var num=function(id,fallback){
    var el=document.getElementById(id);
    if(!el)return fallback;
    var v=Number(el.value);
    return (isFinite(v)&&v>0)?v:fallback;
  };
  settings.calorieGoal=num('trkGoalCal',DEFAULT_GOALS.calorieGoal);
  settings.proteinGoal=num('trkGoalProt',DEFAULT_GOALS.proteinGoal);
  settings.carbGoal=num('trkGoalCarb',DEFAULT_GOALS.carbGoal);
  settings.fatGoal=num('trkGoalFat',DEFAULT_GOALS.fatGoal);
  settings.waterGoal=num('trkGoalWater',DEFAULT_GOALS.waterGoal);
  if(currentUser)saveSettingsFor(currentUser);
  showToast('Goals saved!');
  renderGoalsTab();
}

function renderStats(){
  var g=goals();
  var selKey=statsSelectedKey();
  var selList=diaryFor(selKey);
  var selWater=waterFor(selKey);

  // Totals for selected day
  var totCal=0,totProt=0,totCarbs=0,totFat=0,totWater=0;
  selList.forEach(function(e){totCal+=Number(e.calories)||0;totProt+=Number(e.protein)||0;totCarbs+=Number(e.carbs)||0;totFat+=Number(e.fat)||0;});
  selWater.forEach(function(e){totWater+=Number(e.ml)||0;});

  // Weather for this day
  var wh=getWeatherForDate(selKey);

  // Seven-day chart window ends on the selected history date.
  var days=statsSevenDaysEnding(statsCurrentDate());
  var dn=['Sun','Mon','Tue','Wed','Thu','Fri','Sat'];
  var cal=days.map(function(d){var l=diaryFor(todayKey(d));return{label:dn[d.getDay()],value:l.reduce(function(s,e){return s+(Number(e.calories)||0);},0)};});
  var wat=days.map(function(d){var l=waterFor(todayKey(d));return{label:dn[d.getDay()],value:l.reduce(function(s,e){return s+(Number(e.ml)||0);},0)};});

  var anyData=cal.some(function(c){return c.value>0;})||wat.some(function(w){return w.value>0;})||selList.length>0;
  var box=document.getElementById('statsBody');
  if(!anyData){
    box.innerHTML='<div class="trk-empty"><div class="trk-empty-icon">📈</div><p>Start logging to see your stats!</p></div>';
    return;
  }

  var goalMl=g.waterGoal*250;

  // Summary cards
  var calDays=cal.filter(function(c){return c.value>0;});
  var watDays=wat.filter(function(w){return w.value>0;});
  var avgCal=calDays.length?calDays.reduce(function(s,c){return s+c.value;},0)/calDays.length:0;
  var avgWat=watDays.length?watDays.reduce(function(s,w){return s+w.value;},0)/watDays.length:0;
  var calMet=cal.filter(function(c){return c.value>0&&c.value<=g.calorieGoal;}).length;
  var watMet=wat.filter(function(w){return w.value>=goalMl&&goalMl>0;}).length;
  var best=null;
  cal.forEach(function(c,i){if(c.value>0&&(best===null||c.value<cal[best].value))best=i;});
  var bestTxt=best===null?'\u2014':(cal[best].label+' \u00B7 '+fmtNum(cal[best].value)+' cal');

  // Today's macro summary (old-style inline)
  var macroSummary='<div style="display:grid;grid-template-columns:repeat(2,1fr);gap:6px;margin-bottom:12px">'+
    macroMiniCard('\u{1F525}','Calories',totCal,g.calorieGoal,' cal','#ffb547')+
    macroMiniCard('\u{1F969}','Protein',totProt,g.proteinGoal,'g','#ff5252')+
    macroMiniCard('\u{1F33E}','Carbs',totCarbs,g.carbGoal,'g','#ffc107')+
    macroMiniCard('\u{1F951}','Fat',totFat,g.fatGoal,'g','#4caf50')+
    '</div>';

  // Water summary
  var waterSummary='<div style="background:rgba(255,255,255,.05);border-radius:10px;padding:10px;margin-bottom:12px">'+
    '<div style="font-size:12px;font-weight:700;margin-bottom:4px">\u{1F4A7} Water</div>'+
    '<div style="font-size:13px;font-weight:700">'+fmtNum(totWater)+'ml <span style="font-size:11px;opacity:.5">of '+fmtNum(goalMl)+'ml</span></div>'+
    '<div style="height:6px;border-radius:3px;background:rgba(255,255,255,.1);margin-top:4px;overflow:hidden"><div style="height:100%;width:'+Math.round(Math.min(1,totWater/goalMl)*100)+'%;background:#2196f3;border-radius:3px;transition:width .3s"></div></div>'+
    '</div>';

  // Meals on selected day
  var mealsHtml='';
  if(selList.length>0){
    mealsHtml='<div style="font-size:12px;font-weight:700;margin:4px 0 6px">Meals on '+selKey+'</div>';
    mealsHtml+='<div style="display:flex;flex-direction:column;gap:3px;margin-bottom:12px;max-height:180px;overflow-y:auto">';
    selList.forEach(function(e){
      mealsHtml+='<div style="display:grid;grid-template-columns:1fr auto;gap:2px 6px;padding:6px 8px;background:rgba(255,255,255,.04);border-radius:6px;font-size:11px">'+
        '<span style="font-weight:600">'+escHtml(e.name||'Food')+'</span>'+
        '<span style="text-align:right;font-weight:700;color:#ffb547">'+fmtNum(e.calories||0)+' cal</span>'+
        '<span style="font-size:9px;opacity:.6">'+(e.protein||0)+'g P \u00B7 '+(e.carbs||0)+'g C \u00B7 '+(e.fat||0)+'g F</span>'+
        '<span style="font-size:9px;opacity:.5;text-align:right">'+escHtml(e.time||'')+'</span>'+
        '</div>';
    });
    mealsHtml+='</div>';
  }

  // Weather info
  var wHtml='';
  if(wh){
    wHtml='<div style="font-size:10px;color:#7d8aa8;margin-bottom:8px;padding:5px 8px;background:rgba(74,214,255,.06);border-radius:6px">\u{1F324} '+wh.cond+' \u00B7 '+wh.temp+'\u00B0C'+(wh.hum?' \u00B7 '+wh.hum+'% humidity':'')+'</div>';
  }

  box.innerHTML=
    wHtml+
    macroSummary+
    waterSummary+
    mealsHtml+
    '<div class="stats-chart-title">\u{1F525} Daily Calories \u2014 '+escHtml(statsRangeLabel(days))+'</div>'+
    buildBarChart(cal,g.calorieGoal,' cal','linear-gradient(180deg,#ffb547,#ff7849)')+
    '<div class="stats-chart-title">\u{1F4A7} Daily Water \u2014 '+escHtml(statsRangeLabel(days))+' (ml)</div>'+
    buildBarChart(wat,goalMl,'ml','linear-gradient(180deg,#4ad6ff,#2196f3)')+
    '<div class="stats-cards">'+
      '<div class="stat-card"><div class="stat-val">'+fmtNum(avgCal)+'</div><div class="stat-lbl">Avg daily calories</div></div>'+
      '<div class="stat-card"><div class="stat-val">'+fmtNum(avgWat)+'ml</div><div class="stat-lbl">Avg daily water</div></div>'+
      '<div class="stat-card"><div class="stat-val">'+calMet+' / 7</div><div class="stat-lbl">Days calorie goal met</div></div>'+
      '<div class="stat-card"><div class="stat-val">'+watMet+' / 7</div><div class="stat-lbl">Days water goal met</div></div>'+
      '<div class="stat-card wide"><div class="stat-val">'+escHtml(bestTxt)+'</div><div class="stat-lbl">Best day (lowest calories)</div></div>'+
    '</div>';
}

function macroMiniCard(icon,label,cur,goal,unit,color){
  var pct=0;
  var cv=Number(cur)||0;
  var gv=Number(goal)||0;
  if(gv>0)pct=Math.min(1,cv/gv);
  var dispCur=fmtNum(Math.round(cv));
  var dispGoal=fmtNum(gv);
  return '<div style="background:rgba(255,255,255,.05);border-radius:10px;padding:10px 8px">'+
    '<div style="display:flex;align-items:center;gap:4px;margin-bottom:4px">'+
    '<span style="font-size:14px">'+icon+'</span>'+
    '<span style="font-size:10px;text-transform:uppercase;letter-spacing:.5px;opacity:.7">'+label+'</span>'+
    '</div>'+
    '<div style="font-size:13px;font-weight:700;color:#fff;margin-bottom:4px">'+dispCur+(unit||'')+' <span style="font-size:10px;font-weight:400;opacity:.5">of '+dispGoal+(unit||'')+'</span></div>'+
    '<div style="height:5px;border-radius:3px;background:rgba(255,255,255,.1);overflow:hidden;margin-bottom:3px"><div style="height:100%;width:'+Math.round(pct*100)+'%;background:'+color+';border-radius:3px;transition:width .3s"></div></div>'+
    '<div style="font-size:9px;opacity:.6;text-align:right">'+Math.round(pct*100)+'%</div>'+
    '</div>';
}


function renderAccountInfo(){
  const name=(typeof currentUser==='string'&&currentUser)?currentUser:'';
  const av=document.getElementById('acctAvatar');
  if(av)av.textContent=name?name.charAt(0).toUpperCase():'👤';
  const sub=document.getElementById('acctSub');
  if(!sub)return;
  const key=todayKey();
  const d=getDiary()[key]; const w=getWater()[key];
  const foods=Array.isArray(d)?d.length:0;
  const ml=Array.isArray(w)?w.reduce(function(s,e){return s+(Number(e.ml)||0);},0):0;
  sub.textContent='Today: '+foods+(foods===1?' food':' foods')+' · '+fmtNum(ml)+'ml water · saved on this device';
}
function loadGoalFields(){
  renderAccountInfo();
  const g=goals();
  const set=function(id,v){const el=document.getElementById(id);if(el)el.value=v;};
  set('goalCalories',g.calorieGoal);
  set('goalProtein',g.proteinGoal);
  set('goalWater',g.waterGoal);
  set('goalCarbs',g.carbGoal);
  set('goalFat',g.fatGoal);
  set('edamamAppId',g.edamamAppId);
  set('edamamAppKey',g.edamamAppKey);
  set('usdaApiKey',g.usdaApiKey);
  var fa=document.getElementById('foodApiSelect');
  if(fa){fa.value=g.foodApi||'openfoodfacts';toggleFoodApiFields();}
}
function saveGoalFields(){
  const num=function(id,fallback){
    const el=document.getElementById(id);
    if(!el)return fallback;
    const v=parseFloat(el.value);
    return (isFinite(v)&&v>0)?v:fallback;
  };
  const txt=function(id){const el=document.getElementById(id);return el?el.value.trim():'';};
  settings.calorieGoal=num('goalCalories',DEFAULT_GOALS.calorieGoal);
  settings.proteinGoal=num('goalProtein',DEFAULT_GOALS.proteinGoal);
  settings.waterGoal=num('goalWater',DEFAULT_GOALS.waterGoal);
  settings.carbGoal=num('goalCarbs',DEFAULT_GOALS.carbGoal);
  settings.fatGoal=num('goalFat',DEFAULT_GOALS.fatGoal);
  settings.foodApi=document.getElementById('foodApiSelect')?document.getElementById('foodApiSelect').value:'openfoodfacts';
  settings.edamamAppId=txt('edamamAppId');
  settings.edamamAppKey=txt('edamamAppKey');
  settings.usdaApiKey=txt('usdaApiKey');
}
function toggleFoodApiFields(){
  var sel=document.getElementById('foodApiSelect');
  if(!sel)return;
  var v=sel.value;
  var ed=document.getElementById('edamamFieldsWrap');
  var ek=document.getElementById('edamamKeyWrap');
  var ud=document.getElementById('usdaKeyWrap');
  if(ed)ed.style.display=(v==='edamam')?'block':'none';
  if(ek)ek.style.display=(v==='edamam')?'block':'none';
  if(ud)ud.style.display=(v==='usda')?'block':'none';
}

// INIT
function init(){
  initAuth();
  setupModalListeners();
  const stars=document.getElementById('stars');
  for(let i=0;i<60;i++){const s=document.createElement('div');s.className='star';s.style.left=Math.random()*100+'%';s.style.top=Math.random()*60+'%';s.style.animationDelay=Math.random()*3+'s';s.style.width=s.style.height=(1+Math.random()*2)+'px';stars.appendChild(s);}
  const landscape=document.querySelector('.landscape');
  [5,15,28,42,55,68,82,92].forEach(pos=>{const t=document.createElement('div');t.className='tree';t.style.left=pos+'%';t.style.transform='scale('+(0.6+Math.random()*0.5)+')';t.style.bottom=(20+Math.random()*30)+'px';landscape.appendChild(t);});
  const now=new Date().getHours();const sky=document.getElementById('sky');sky.className='sky';
  if(now>=5&&now<11)sky.classList.add('morning-default');else if(now>=11&&now<17)sky.classList.add('afternoon-default');else if(now>=17&&now<20)sky.classList.add('evening-default');else sky.classList.add('night-default');
  updateApiStatus();updateProviderInfo();
  loadMLModel().then(function(){if(lastWeather&&settings.recommendationMode!=='rules'){displayRecommendations(recommendFood(lastWeather,settings.recoCount),lastWeather);}});
  try{renderDiary();}catch(e){}
}
init();

